/**
 * Represents a UK BNF nomenclature record returned by the OpenPrescribing API:
 * `https://openprescribing.net/api/1.0/bnf_code/?format=json&q={searchTerm}`
 */
export interface BnfMedicationItem {
  /** BNF Code / ID (e.g., "0407010H0", "0301011R0") */
  id: string;
  /** UK BNF / rINN nomenclature name (e.g., "Paracetamol", "Salbutamol") */
  name: string;
  /** Optional entity type returned by OpenPrescribing (e.g., "chemical", "product", "presentation", "section") */
  type?: string;
}

/**
 * Clinical details dynamically generated by the Gemini API for a selected UK medication
 * in Standard Mode.
 */
export interface GeminiClinicalDetails {
  phoneticSpelling: string;
  class: string;
  indications: string[];
  /**
   * Plain-English, pre-hospital summary explaining why a patient is typically prescribed
   * this medication and what an ambulance crew needs to be aware of on scene.
   */
  medicSummary: string;
}

/**
 * Overdose & toxicology details dynamically generated by the Gemini API for a selected UK
 * medication when Toxicity Mode is active.
 */
export interface GeminiToxicityDetails {
  /** Plain-English summary of how the overdose presents clinically and vital sign changes */
  overdoseEffects: string;
  /** Known toxic dose limit, e.g., '>75mg/kg' or specific mg amount */
  toxicThreshold: string;
}

/**
 * Holistic analysis returned by Gemini Vision when scanning an uploaded prescription
 * or repeat medication list.
 */
export interface PrescriptionScanResult {
  /** Distinct UK generic/BNF medication names detected in the image */
  medications: string[];
  /**
   * Standard Mode: Plain-English summary of what medical conditions the patient likely
   * suffers from given the combination of prescribed medications, plus generalised
   * pre-hospital on-scene context for the ambulance crew.
   */
  patientProfileSummary: string;
  /**
   * Toxicity Mode: Pre-hospital toxicology & polypharmacy summary focusing on dangerous
   * drug-drug interactions, synergistic overdose effects, and key clinical red flags
   * across the prescribed medications.
   */
  toxicityInteractionsSummary: string;
}

export type SpeechSpeed = 1.0 | 0.75;
